import{_ as e,o,c as t,a3 as _}from"./chunks/framework.DdpBa4_E.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/money-dog/24-附-录.md","filePath":"books/money-dog/24-附-录.md","lastUpdated":1781445373000}'),a={name:"books/money-dog/24-附-录.md"};function s(n,p,r,d,c,m){return o(),t("div",null,[...p[0]||(p[0]=[_("<p>附　录</p><p>股票</p><p>股票是一家公司的股权证明——你可以购买这家公司的一份或若干份股权。每一份股权就是一张股票。如果公司赢利（赚钱），你就可以根据自己所拥有的股份数量，从公司的利润中分得一部分。你的股份越少，分到的利润就越少；股份越多，分到的利润就越多。如果公司亏损，那么你所持有的股票就会贬值。在这种情况下，你不应该急于卖出股票，而应该等待公司重新赢利。在第十六章中，陶穆太太对此有详细说明。</p><p>投资</p><p>一方面，投资是指通过获取利息使钱的数目增加，比如将钱投资买股票，或者存入银行；另一方面，通过购买任何一件日后会增值的物品，比如艺术品、房产、古董等，也可以进行投资。</p><p>交易所</p><p>交易所是一种特别的市场，是商人们为了进行商业交易而举行定期聚会的场所。交易所根据市场情况，并且通过官方的价格调控使供应和需求达到平衡。详情请见第十六章。</p><p>基金</p><p>出于特定用途而集中的资金（特殊财产），详情请参阅第十六章。</p><p>抵押</p><p>简而言之，抵押就是把地产等抵押品作为债务担保的行为。当房子所有权人负债时，他可以抵押这栋房子，作为法律上和经济上还款的保证，但这样一来，他的地产就记入了债权人名下。这就是说，这栋房子的所有权受到了限制，如果债务人——也就是房子所有权人——出售他的房子，获得的收益必须交给债权人。</p><p>通货膨胀</p><p>通货膨胀就是货币贬值。现在用5马克可以比10年后买到更多的东西，也就是说，货币的价值随着时间的增长而不断减少。</p><p>利息</p><p>如果你将资金借给银行（就是说把钱存入一个账户），银行就付给你一定的金额作为回报。如果你借给银行3000马克，银行就会按一个规定的利率——比如3％，付给你利息，这样你每年都会得到3000马克的3％，也就是90马克。</p><p>复利</p><p>你可以和银行约定，每年年终时将利息计入本金。我们还以上面的数字为例，那么你第二年的本金加在一起就达到了3090马克，这笔钱又重新开始产生利息：3090的3％是92.7马克。这样继续下去，下一年的本金就是：3090＋92.7＝3182.70（马克）。以此类推，之后每年都这样计算。</p>",17)])])}const f=e(a,[["render",s]]);export{l as __pageData,f as default};
